pub(super) fn messages(locale: &str) -> &'static [Message] {
    match locale {
        "de" => MESSAGES_DE,
        "en-GB" => MESSAGES_EN_GB,
        "es" => MESSAGES_ES,
        "fr" => MESSAGES_FR,
        "ja" => MESSAGES_JA,
        "ko" => MESSAGES_KO,
        "pt-BR" => MESSAGES_PT_BR,
        "ru" => MESSAGES_RU,
        "uk" => MESSAGES_UK,
        "zh-CN" => MESSAGES_ZH_CN,
        "zh-TW" => MESSAGES_ZH_TW,
        _ => &[],
    }
}
